import { useState } from 'react';

export function useStep(steps) {
  const [index, setIndex] = useState(0);
  return {
    current: steps[index],
    index,
    next: () => setIndex(i => Math.min(i + 1, steps.length - 1)),
    prev: () => setIndex(i => Math.max(i - 1, 0)),
    isFirst: index === 0,
    isLast: index === steps.length - 1,
  };
}
